/**
 * The admin API's JSON: what every route of admin-api answers, typed. The dashboard (`src/dashboard/`,
 * a project of its own) keeps an identical copy, `src/dashboard/src/lib/admin-api.ts`: no imports, so
 * it compiles there too. Change both together; the kit's tests check they are the same.
 *
 * Every route needs an operator (`admin.auth`): `Authorization: Bearer <PIKIT_ADMIN_TOKEN>` with
 * admin-auth-token, or the session cookie a browser got from `POST /admin/api/session` (then a `POST`
 * also carries `x-pikit-admin: 1`). An error is an `ApiError` with its status.
 *
 * **The dashboard is a channel of its own.** It reads every conversation, and writes only into its own
 * (keys `dashboard:<uuid>`, `POST /admin/api/conversations`) and as follow-ups to another channel's
 * conversation, whose answers it keeps: the request ids of its messages start with `dashboard:`, and a
 * run only they started is never delivered to the conversation's chat.
 *
 * | Route | Answer |
 * |---|---|
 * | `GET /admin/api/app` | `ApiApp`: the composition (`APP_DESCRIPTION`, no secrets) |
 * | `GET /admin/api/agents` | `ApiAgents`: the App's agents (the code's, then the live ones), their model and tools, and which is the steward; every tool and skill an agent may have, each with its one line |
 * | `POST /admin/api/session` | the credential once → `200 ApiSession` and a session cookie (a browser's) |
 * | `DELETE /admin/api/session` | `204`: the session cookie cleared |
 * | `GET /admin/api/conversations?limit&cursor&archived&q` | `ApiPage<ApiConversation>`, the most recently active first: those listed, or with `archived=1` those archived; with `q` (at most `SEARCH_MAX` characters), only those whose title or key holds it, any case |
 * | `POST /admin/api/conversations` | `ApiStartRequest` → `201 ApiStartResponse`: a conversation of the dashboard's own |
 * | `GET /admin/api/conversations/:id` | `ApiConversation` |
 * | `GET /admin/api/conversations/:id/transcript?limit&cursor` | `ApiPage<ApiTranscriptEntry>`, newest first |
 * | `GET /admin/api/conversations/:id/events` | server-sent events, one `ApiEvent` per `data:` line; `snapshot` first |
 * | `POST /admin/api/conversations/:id/messages` | `ApiSendRequest` → `202 ApiSendResponse` |
 * | `POST /admin/api/conversations/:id/abort` | `200 ApiAbortResponse` |
 * | `POST /admin/api/conversations/:id/reset` | `200 ApiResetResponse` |
 * | `POST /admin/api/conversations/:id/archive`, `…/unarchive`, `…/delete` | `200 ApiHideResponse`: the list only (a deleted one is never listed again, nothing of the runtime's is deleted; new activity lists either again) |
 * | `POST /admin/api/conversations/:id/rename` | `ApiRenameRequest` → `200 ApiConversation`: the operator's title (`cleanTitle`), as `/name` sets it, on any conversation, current or not |
 * | `GET /admin/api/commands` | `ApiCommands`: the slash commands the App registered (`agent.command`) |
 * | `POST /admin/api/conversations/:id/commands/:name` | `ApiCommandRequest` → `200 ApiCommandResponse`: the command run in the conversation |
 * | `GET /admin/api/delivery/pending?limit&cursor` | `ApiPage<ApiPendingPiece>`, oldest stored first (with `outbound.queue`) |
 * | `GET /admin/api/delivery/receipts?after&limit` | `ApiReceiptsPage`, in the order they settled (with `outbound.queue`) |
 */

/** The keys of the dashboard's own conversations: `dashboard:<uuid>`. No other channel makes one. */
export const DASHBOARD_KEY_PREFIX = "dashboard:";

/** Whether `key` is one of the dashboard's own conversations. */
export const isDashboardKey = (key: string | undefined): boolean => key?.startsWith(DASHBOARD_KEY_PREFIX) === true;

/** How every message from the dashboard starts, as the agent reads it (`operatorPrompt`). */
export const OPERATOR_NOTE = "[From the operator, in the pikit dashboard";

/** The tool an agent searches the web with (`tool-websearch-brave` provides it under this name). */
export const WEB_SEARCH_TOOL = "websearch";

/**
 * `text` as the agent reads it, sent from the dashboard to the conversation `key`: a first line says it
 * comes from the operator, and, in another channel's conversation, that its user sees neither it nor
 * the answer; with `webSearch`, that the agent is to search the web for it (`WEB_SEARCH_TOOL`).
 */
export function operatorPrompt(key: string, text: string, options: { webSearch?: boolean } = {}): string {
  const asks = [
    ...(isDashboardKey(key) ? [] : ["the user of this conversation does not see this message or your answer to it"]),
    ...(options.webSearch === true ? [`search the web for it with the ${WEB_SEARCH_TOOL} tool before you answer`] : []),
  ];
  const note = asks.length === 0 ? `${OPERATOR_NOTE}.]` : `${OPERATOR_NOTE}: ${asks.join("; ")}.]`;
  return `${note}\n${text}`;
}

/** The longest title a conversation has (`cleanTitle`). */
export const TITLE_MAX = 60;

/** The longest search of the conversations (`q`). */
export const SEARCH_MAX = 200;

/** Labels a model may put before a title ("Title: …"), in a few languages: taken off. */
const TITLE_LABEL = /^(?:title|name|subject|topic|t\u00edtulo|titulo|titre|titel|titolo|nombre|nom)(?:\s*:\s*|\s+[-\u2013\u2014]\s+)/i;
/** Quotes and markdown a title is wrapped in. */
const TITLE_WRAP = /^[\s"'`*_#>\u2018\u2019\u201c\u201d\u00ab\u00bb\u300c\u300d-]+|[\s"'`*_\u2018\u2019\u201c\u201d\u00ab\u00bb\u300c\u300d]+$/g;

/**
 * A presentable title from `text` (a model's answer, or what an operator wrote with `/name`), or
 * `undefined` when nothing is left: its first line that has words, without a label ("Title:"),
 * quotes or markdown around it, its spaces collapsed, no `.`, `,`, `;` or `:` at its end, its first
 * letter a capital, at most `TITLE_MAX` characters (cut at a word, with an ellipsis).
 */
export function cleanTitle(text: string): string | undefined {
  const line = text
    .split(/\r?\n/)
    .map((each) => each.replace(TITLE_WRAP, "").replace(TITLE_LABEL, "").replace(TITLE_WRAP, "").replace(/\s+/g, " ").trim())
    .find((each) => /[\p{L}\p{N}]/u.test(each));
  if (line === undefined) return undefined;
  let title = line.replace(/[.,;:\s]+$/u, "");
  if (title.length > TITLE_MAX) {
    const cut = title.slice(0, TITLE_MAX - 1);
    const space = cut.lastIndexOf(" ");
    title = `${(space >= TITLE_MAX / 3 ? cut.slice(0, space) : cut).replace(/[.,;:\s]+$/u, "")}\u2026`;
  }
  return title === "" ? undefined : title.charAt(0).toLocaleUpperCase() + title.slice(1);
}

/** The images an operator may attach to a message: these types, `MAX_IMAGES` of `MAX_IMAGE_BYTES` at most. */
export const IMAGE_TYPES: readonly string[] = ["image/png", "image/jpeg", "image/webp", "image/gif"];
export const MAX_IMAGES = 4;
export const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
/**
 * On Cloudflare (`ApiApp.target` `durable`), the images of one message in all: the message is stored in
 * one Durable Object row, which holds at most 2 MB, and the images grow by a third in base64.
 */
export const MAX_DURABLE_IMAGE_BYTES = 1024 * 1024;

/** The bytes base64 `data` decodes to. */
export const base64Bytes = (data: string): number => Math.floor((data.length * 3) / 4) - (data.endsWith("==") ? 2 : data.endsWith("=") ? 1 : 0);

const BASE64 = /^[A-Za-z0-9+/]*={0,2}$/;

/**
 * What is wrong with a message's `attachments`, or `undefined`: too many, not an image of
 * `IMAGE_TYPES`, or not base64 (`400`); one larger than `MAX_IMAGE_BYTES`, or on `target` `durable`
 * more than `MAX_DURABLE_IMAGE_BYTES` in all (`413`). The dashboard checks with it before sending, and
 * the API again.
 */
export function attachmentsProblem(attachments: readonly ApiAttachment[], target?: string): { status: 400 | 413; message: string } | undefined {
  if (attachments.length > MAX_IMAGES) return { status: 400, message: `at most ${MAX_IMAGES} images a message` };
  let total = 0;
  for (const [i, attachment] of attachments.entries()) {
    if (attachment.kind !== "image" || !IMAGE_TYPES.includes(attachment.mimeType)) return { status: 400, message: `attachment ${i + 1}: an image is ${IMAGE_TYPES.join(", ")}` };
    if (attachment.data.length % 4 !== 0 || !BASE64.test(attachment.data)) return { status: 400, message: `attachment ${i + 1}: its data is not base64` };
    const bytes = base64Bytes(attachment.data);
    if (bytes > MAX_IMAGE_BYTES) return { status: 413, message: `attachment ${i + 1}: an image is at most ${MAX_IMAGE_BYTES / 1024 / 1024} MB` };
    total += bytes;
  }
  if (target === "durable" && total > MAX_DURABLE_IMAGE_BYTES) {
    return { status: 413, message: `on Cloudflare the images of a message are at most ${MAX_DURABLE_IMAGE_BYTES / 1024 / 1024} MB in all (a Durable Object row holds 2 MB)` };
  }
  return undefined;
}

/** What a conversation cost: every model call and tool summed (pi-ai's `Usage`). */
export interface ApiUsage {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
  totalTokens: number;
  cost: { input: number; output: number; cacheRead: number; cacheWrite: number; total: number };
}

/**
 * Who a conversation is with, as its channel describes it (`conversation.describe`), or as its key says
 * when no channel describes it.
 */
export interface ApiParty {
  /**
   * The channel: its kind (`web`, `telegram`, `googlechat`, `http`, `dashboard`…), the instance when not
   * the default (`support` of `telegram:support`), and how it reads ("Web chat", "Telegram", "Google
   * Chat", "HTTP API", "Dashboard").
   */
  channel: { kind: string; instance?: string; label: string };
  /** The person or the chat, readable: "Ana López", "@ana", "Ops team" (a group, a space). Absent when not known. */
  name?: string;
  /** One more line: an email, a group's or space's name, "Direct message". */
  detail?: string;
  /**
   * Identifiers an operator may need, each with a label ("User id", "Chat id", "Space", "Key",
   * "Conversation"), in order. The last two are always the conversation key and the runtime's id.
   */
  ids: { label: string; value: string }[];
  /** A dashboard path about this party ("/channel-web?user=…", the Web users page, filtered), when there is one. */
  link?: { label: string; path: string };
}

/** One conversation of the runtime. */
export interface ApiConversation {
  /**
   * What `:id` is in the routes, opaque (encode it in a path): the runtime's id on a server,
   * `<key>~<the object's id>` on Cloudflare, where each conversation's object numbers its own.
   */
  conversationId: string;
  /**
   * Its conversation key (`telegram:12345`) and agent, once a message reached it or a reset pointed
   * its key to it (a reset's new conversation is its key's current one, talked to at once).
   */
  key?: string;
  agent?: string;
  /** Whether a run is going now. */
  busy: boolean;
  /** Epoch ms of its newest message. */
  lastActivity?: number;
  usage: ApiUsage;
  /**
   * Whether its key points to it now. `false` for a conversation a reset left behind: it can be read,
   * not talked to. Absent when it has no key: no message reached it and no reset pointed a key to it.
   */
  current?: boolean;
  /**
   * Its title (`cleanTitle`): the one a model gave it after its first run, or the operator's (`/name`).
   * Until it has one, its first message (cleaned the same way) once a model was asked to title it. A
   * reset's new conversation has its own. Absent until then.
   */
  title?: string;
  /** Who it is with (`ApiParty`): present whenever it has a key. */
  party?: ApiParty;
}

/** One page, and the cursor of the next (absent on the last page). */
export interface ApiPage<T> {
  items: T[];
  next?: string;
}

/** One entry of a conversation's history: its messages in the runtime's JSON (pi-ai's `Message`). */
export interface ApiTranscriptEntry {
  id: string;
  /** `message`, `pi.reset`, …: the runtime's words. */
  kind: string;
  messages: unknown[];
}

/**
 * One live event of a conversation, in the runtime's JSON. The first is a `snapshot` of what the
 * conversation is now; a client that fell behind gets a new `snapshot`, so a view is rebuilt from the
 * last `snapshot` and the events after it, never from a count of events.
 */
export interface ApiEvent {
  type: string;
  [field: string]: unknown;
}

/** One of the App's agents (`agent.definition`, or a live one of `agent.directory`), as it is defined. */
export interface ApiAgent {
  name: string;
  /** An agent that is data (`agent.directory`: made in the dashboard, agents-live), not the code's. */
  live?: true;
  /** A live agent's one line: what it is for. */
  description?: string;
  /** `provider/modelId`. */
  model: string;
  /**
   * The names of the tools it is defined with (its `tools`; a tool object by its name). Not the tools
   * its extensions bring, nor those a `prepare` gives for a state.
   */
  tools: string[];
  /** Whether it is the project's steward (`steward: true` in its `defineAgent`, SPEC §6): at most one is. */
  steward: boolean;
}

export interface ApiAgents {
  /** By name: the code's, then the live ones. */
  items: ApiAgent[];
  /**
   * Every tool an agent may have, by name: the installed ones (`agent.tool`), then those a code agent's
   * definition holds itself. What the Agent sections show next to each tool's switch.
   */
  tools: ApiSummary[];
  /** Every skill an agent may have, by name: the project's (`agent.skill`), then those a code agent's definition holds itself. */
  skills: ApiSummary[];
}

/** A tool or a skill, and what it does in one short line, for an operator. */
export interface ApiSummary {
  name: string;
  /**
   * A tool's `summary`, the line its component wrote for an operator; else (a skill, or a tool without
   * one) its description's first sentence; at most `SUMMARY_MAX` characters (cut at a word, with an
   * ellipsis). Empty when it has no description.
   */
  summary: string;
}

/** The longest `ApiSummary.summary`. */
export const SUMMARY_MAX = 90;

/** An image attached to a message: the model reads it with the text, and the transcript keeps it. */
export interface ApiImageAttachment {
  kind: "image";
  /** One of `IMAGE_TYPES`. */
  mimeType: string;
  /** Its bytes, base64 (standard, padded), without a `data:` prefix: at most `MAX_IMAGE_BYTES`. */
  data: string;
}

export type ApiAttachment = ApiImageAttachment;

/**
 * A message from an operator to a conversation: a follow-up (with a run going it waits for it), whose
 * answer stays in the dashboard. The agent reads it after `operatorPrompt`'s first line.
 */
export interface ApiSendRequest {
  /** May be empty when it has attachments. */
  text: string;
  /** Images, at most `MAX_IMAGES` (`attachmentsProblem`: `400`, `413`). */
  attachments?: ApiAttachment[];
  /**
   * The agent is told, in the message's first line, to search the web for it. Only for an agent with
   * the tool `WEB_SEARCH_TOOL`: another is `400`.
   */
  webSearch?: boolean;
  /**
   * Its identity: the same one sent again does not run again. `dashboard:` then 1 to 118 of
   * `A-Z a-z 0-9 . _ ~ : -`. Absent, admin-api makes one.
   */
  requestId?: string;
}

export interface ApiSendResponse {
  requestId: string;
  /** `started`: a run started; `queued`: it waits for the run going; `duplicate`: already there. */
  admission: "started" | "queued" | "duplicate";
}

/** A new conversation of the dashboard's own, with its first message. */
export interface ApiStartRequest {
  /** One of the App's agents (`GET /admin/api/agents`): the code's, or a live one. */
  agent: string;
  /** As `ApiSendRequest`'s. */
  text: string;
  attachments?: ApiAttachment[];
  webSearch?: boolean;
  /** As `ApiSendRequest.requestId`. */
  requestId?: string;
}

export interface ApiStartResponse extends ApiSendResponse {
  conversationId: string;
  /** `dashboard:<uuid>`. */
  key: string;
}

/** A slash command the App registered (`agent.command`), as a menu lists it. */
export interface ApiCommand {
  /** Without its slash: `new`, `name`, `compact`. */
  name: string;
  /** One line. */
  description: string;
  /** What its arguments are: `<title>`. Absent: it takes none. */
  argumentHint?: string;
}

export interface ApiCommands {
  /** By name. Empty when the App registered none. */
  items: ApiCommand[];
}

/** A command run in a conversation: what follows its name. */
export interface ApiCommandRequest {
  /** The text after `/name `, at most `MAX_COMMAND_ARGS` characters; absent or empty: none. */
  args?: string;
}

/** The longest arguments a command takes, in characters. */
export const MAX_COMMAND_ARGS = 4_000;

/**
 * What a command answered: a note for the operator (the dashboard shows it in the conversation,
 * quietly; no channel gets it, and it is in the transcript only if the command wrote there), or none.
 */
export interface ApiCommandResponse {
  text?: string;
}

/** A browser's session, opened. */
export interface ApiSession {
  /** The operator's id, as `admin.auth` names it. */
  operator: string;
}

export interface ApiAbortResponse {
  conversationId: string;
}

/** A conversation's new title, the operator's: cleaned (`cleanTitle`), it replaces any, and no model replaces it. */
export interface ApiRenameRequest {
  /** Something to title it with once cleaned; at most `MAX_COMMAND_ARGS` characters before. */
  title: string;
}

/** What archive, unarchive and delete did: the conversation, put away or back in the list. */
export interface ApiHideResponse {
  conversationId: string;
}

export interface ApiResetResponse {
  key: string;
  /** The conversation the key pointed to, kept and readable. */
  previousConversationId: string;
  /** The new, empty conversation the key points to now. */
  conversationId: string;
}

/** A piece of an answer not delivered yet (`outbound.queue`'s `pending`). Never its text. */
export interface ApiPendingPiece {
  idempotencyKey: string;
  /**
   * The conversation it answers, as this API names it (`:id`): from a run's answer key
   * (`answerKey`: `${conversationId}:${requestId}`); absent for a key of another shape.
   */
  conversationId?: string;
  /** Which of the answer's pieces: 0 is the first. */
  index: number;
  channel: string;
  conversationKey: string;
  /** `queued`: never tried; `sending`: in flight; `retrying`: tried, waiting to go again. */
  state: "queued" | "sending" | "retrying";
  attempts: number;
  /** Epoch ms before which it is not tried again; absent while sending. */
  nextAttemptAt?: number;
  /** Why its last try did not deliver it, short. */
  lastError?: string;
  /** Its next send may repeat one that reached the platform. */
  possibleDuplicate: boolean;
  storedAt: number;
}

/** A piece that settled (`outbound.queue`'s `receipts`), with the cursor to read after it. */
export interface ApiReceipt {
  cursor: string;
  idempotencyKey: string;
  /** As `ApiPendingPiece.conversationId`. */
  conversationId?: string;
  index: number;
  channel: string;
  conversationKey: string;
  attempts: number;
  outcome: { kind: "delivered"; platformMessageId: string; possibleDuplicate: boolean } | { kind: "abandoned"; reason: string };
  /** Epoch ms when it settled. */
  at: number;
}

/** Receipts after a cursor: `next` is the last one's, to read on from; `gap`: some were pruned before this read. */
export interface ApiReceiptsPage {
  items: ApiReceipt[];
  gap: boolean;
  next?: string;
}

/**
 * The composition (`AppDescription`, K13): JSON, no secrets. A config value that looks like one (under a
 * key such as `token`, `secret`, `password`, `apiKey`, or shaped like a credential) is `[redacted]`.
 */
export interface ApiApp {
  version: number;
  target: string;
  components: { name: string; version?: string; provides: string[]; requires: string[]; optional: string[] }[];
  capabilities: Record<string, { providers: string[]; selected?: string; keys?: Record<string, string> }>;
  pipelines: Record<string, unknown[]>;
  config: Record<string, unknown>;
}

export interface ApiError {
  /**
   * `unauthorized`, `not_found`, `not_installed`, `invalid_request`, `invalid_cursor`, `no_agent`,
   * `not_current`, `unknown_agent`, `too_large` (413: an image, or a body, larger than the API takes),
   * `unknown_command` (404: no command of that name), `command_failed` (422: the command could not do
   * it, its message says why);
   * `unavailable` (503) when, on Cloudflare, a conversation's object did not answer.
   */
  error: string;
  message?: string;
}

/**
 * The admin API (admin-api, `/admin/api/*`), from the browser. Its JSON is typed in `admin-api.ts`, an
 * identical copy of admin-api's own `api.ts` (`src/pikit/admin-api/api.ts`): change both together.
 *
 * **Signing in** (`signIn`) posts the operator's token once, to `POST /admin/api/session`, which
 * answers with a session cookie (HttpOnly, SameSite=Strict, sent to `/admin/api/` only, expiring):
 * the token is kept nowhere, and no script can read the session. `signOut` clears it. Every call
 * carries the header `x-pikit-admin: 1`, which a page of another site cannot send, so the cookie
 * alone changes nothing. An `admin.auth` without browser sessions (`404 not_installed`): the token is
 * kept in this page's memory only, and asked again after a reload.
 *
 * A browser's `EventSource` cannot send the header, so live events are read with `fetch`.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { usePolling } from "./activity.ts";
import type { ApiError, ApiEvent, ApiSession } from "./admin-api.ts";

export type * from "./admin-api.ts";

const API = "/admin/api";
/** `ADMIN_CLIENT_HEADER` (@pikit/contracts): what makes a call the dashboard's own. */
const CLIENT_HEADER = "x-pikit-admin";

/** The token, when the API has no browser sessions: this page's memory only. */
let memoryToken: string | undefined;

/** An answer that is not a success: its status and the API's error. */
export class ApiFailure extends Error {
  readonly status: number;
  readonly body: ApiError;
  constructor(status: number, body: ApiError) {
    super(body.message ?? body.error);
    this.status = status;
    this.body = body;
  }
}

/** Listeners told when the API refuses the token (401): the app asks for it again. */
const unauthorized = new Set<() => void>();
export function onUnauthorized(listener: () => void): () => void {
  unauthorized.add(listener);
  return () => unauthorized.delete(listener);
}

function headers(extra?: HeadersInit): Headers {
  const all = new Headers(extra);
  all.set(CLIENT_HEADER, "1");
  if (memoryToken !== undefined) all.set("authorization", `Bearer ${memoryToken}`);
  return all;
}

/**
 * Signs in with the operator's `token` (PIKIT_ADMIN_TOKEN with admin-auth-token): a session cookie,
 * or, without browser sessions, the token in memory. Answers the operator's id when the API names it.
 * Throws an `ApiFailure` (`401`: not the token).
 */
export async function signIn(token: string): Promise<string | undefined> {
  const response = await fetch(`${API}/session`, { method: "POST", headers: { [CLIENT_HEADER]: "1", authorization: `Bearer ${token}` } });
  if (response.ok) {
    memoryToken = undefined;
    const session = (await response.json().catch(() => undefined)) as ApiSession | undefined;
    return typeof session?.operator === "string" ? session.operator : undefined;
  }
  const body = (await response.json().catch(() => ({ error: `http_${response.status}` }))) as ApiError;
  if (response.status !== 404 || body.error !== "not_installed") throw new ApiFailure(response.status, body);
  // No sessions: the token goes with every call, from memory, if the API takes it.
  memoryToken = token;
  try {
    await api("/app");
  } catch (error) {
    memoryToken = undefined;
    throw error;
  }
  return undefined;
}

/** Signs out: the session cookie cleared (and the token forgotten). */
export async function signOut(): Promise<void> {
  memoryToken = undefined;
  await fetch(`${API}/session`, { method: "DELETE", headers: { [CLIENT_HEADER]: "1" } }).catch(() => undefined);
}

async function failure(response: Response): Promise<ApiFailure> {
  if (response.status === 401) for (const listener of unauthorized) listener();
  const body = (await response.json().catch(() => ({ error: `http_${response.status}` }))) as ApiError;
  return new ApiFailure(response.status, body);
}

/** `GET` (or `init`'s method) of `path` under /admin/api, as JSON; `undefined` for a `204` (a `DELETE`'s). */
export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(`${API}${path}`, { ...init, headers: headers(init.headers) });
  if (!response.ok) throw await failure(response);
  if (response.status === 204) return undefined as T;
  return (await response.json()) as T;
}

/** `POST` of `body` (JSON) to `path` under /admin/api. */
export function post<T>(path: string, body?: unknown): Promise<T> {
  return api<T>(path, {
    method: "POST",
    headers: { "content-type": "application/json" },
    ...(body !== undefined && { body: JSON.stringify(body) }),
  });
}

/**
 * Follows `path`'s server-sent events until `signal` aborts or the stream ends: each `data:` line is
 * one event. Resolves when the stream ends; rejects when it cannot start.
 */
export async function follow(path: string, onEvent: (event: ApiEvent) => void, signal: AbortSignal): Promise<void> {
  const response = await fetch(`${API}${path}`, { headers: headers({ accept: "text/event-stream" }), signal });
  if (!response.ok || response.body === null) throw await failure(response);
  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) return;
      buffer += value;
      let end = buffer.indexOf("\n\n");
      while (end !== -1) {
        const frame = buffer.slice(0, end);
        buffer = buffer.slice(end + 2);
        const data = frame
          .split("\n")
          .filter((line) => line.startsWith("data: "))
          .map((line) => line.slice(6))
          .join("\n");
        if (data !== "" && !frame.startsWith("event: error")) onEvent(JSON.parse(data) as ApiEvent);
        end = buffer.indexOf("\n\n");
      }
    }
  } catch (error) {
    if (signal.aborted) return;
    throw error;
  } finally {
    reader.releaseLock();
  }
}

export interface Loaded<T> {
  data: T | undefined;
  error: Error | undefined;
  loading: boolean;
  reload(): void;
}

/** `GET path`, again on `reload()`, and every `everyMs` when given while the dashboard is active. `null` loads nothing. */
export function useApi<T>(path: string | null, everyMs?: number): Loaded<T> {
  const [data, setData] = useState<T>();
  const [error, setError] = useState<Error>();
  const [loading, setLoading] = useState(path !== null);
  const [round, setRound] = useState(0);
  const current = useRef(path);
  current.current = path;

  useEffect(() => {
    if (path === null) return;
    let live = true;
    setLoading(true);
    api<T>(path)
      .then((value) => live && current.current === path && (setData(value), setError(undefined)))
      .catch((thrown: unknown) => live && setError(thrown instanceof Error ? thrown : new Error(String(thrown))))
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
  }, [path, round]);

  const reload = useCallback(() => setRound((n) => n + 1), []);
  // Only while the operator is here (`activity.ts`).
  usePolling(reload, path === null ? undefined : everyMs);
  return { data, error, loading, reload };
}

/**
 * The conversations the sidebar and the tabs show: the most recently active (the API's index: its
 * first `PAGE`, which the sidebar lists, read again every 10 s while the dashboard is active, 30 s on
 * Cloudflare; never more: every one is on the Conversations page, `views/conversations/list.tsx`), the
 * tabs the operator opened, what the commands answered, and the messages sent from here that the
 * conversation does not show yet (shown at once, where they go). A conversation written to from here
 * goes first at once (`writtenFirst`), and the list is read again once the message is in (the open
 * conversation's page calls `reload`).
 *
 * A title names one conversation (a reset's new one has its own). It is the API's
 * (`ApiConversation.title`: a model's, made after its first run, or the operator's, `/name` or `rename`; until then
 * its first message, once a model was asked to title it); until there is one, its first message when
 * this page has it at hand (sent from New chat, or read in the open conversation's transcript: never
 * looked for), else for another channel's conversation who it is with (its party's name), else the id
 * in its key (`telegram:12345` is `12345`), and "New
 * chat" for one of the dashboard's own. A conversation with no key (no message reached it and no reset
 * pointed a key to it) has nothing to show or do: the list leaves it out. Tabs are kept in
 * `localStorage["pikit-tabs"]`.
 *
 * The operator puts a conversation away from its row (`hide`): archived (listed apart: the
 * Conversations page's Archived; `archived` here, read when asked, says whether the conversation shown
 * is one) or deleted (never listed again). The list only: the runtime keeps it, and new activity (a
 * person writes again) lists it again by itself. Each change made here moves `changed`, which a list
 * of its own (the Conversations page) follows.
 */

import { createContext, type ReactNode, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { type SentMessages, useSentMessages, writtenFirst } from "@/components/pikit/conversation";
import { every, usePolling } from "./activity.ts";
import { cleanTitle, isDashboardKey } from "./admin-api.ts";
import { type ApiAgent, api, type ApiApp, type ApiConversation, type ApiPage, type ApiRenameRequest, post } from "./api.ts";

/** The conversations read: the sidebar's (`SIDEBAR_CHATS`). */
const PAGE = 20;
/** The archived ones read when asked. */
const ARCHIVED_PAGE = 50;
const TABS = "pikit-tabs";
/** Tabs kept. */
const KEPT_TABS = 12;
/** The title of a dashboard conversation with no title and no first message at hand. */
export const NEW_CHAT = "New chat";

/** What a command answered in a conversation: a quiet note there, in this page only (no channel gets it). */
export interface CommandNote {
  id: number;
  /** The command, without its slash. */
  command: string;
  text: string;
  at: number;
}

let nextNote = 0;

export interface Tab {
  id: string;
  /** Its conversation's title when it was opened; the API's newer one wins. */
  title: string;
}

function load<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key);
    return raw === null ? fallback : (JSON.parse(raw) as T);
  } catch {
    return fallback;
  }
}

function save(key: string, value: unknown): void {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // Not kept: this page still has it.
  }
}

/**
 * The App's agents: those `GET /admin/api/agents` listed (`described`: the code's, then the live ones),
 * else, until it answered, the keys of `agent.definition`.
 */
export const agentsOf = (app: ApiApp | undefined, described?: readonly ApiAgent[]): string[] =>
  described !== undefined ? described.map((agent) => agent.name) : Object.keys(app?.capabilities["agent.definition"]?.keys ?? {}).sort();

/** The agent the App answers with when none is named (router-basic's `defaultAgent`), if it is one of `agents`. */
export function defaultAgentOf(app: ApiApp | undefined): string | undefined {
  const agents = agentsOf(app);
  const named = (app?.config["router-basic"] as { defaultAgent?: unknown } | undefined)?.defaultAgent;
  return typeof named === "string" && agents.includes(named) ? named : agents[0];
}

/** With the messages sent from here and not shown yet (`SentMessages`, the shared conversation view's). */
export interface Chats extends SentMessages {
  /** Undefined until the first page is read. */
  items: ApiConversation[] | undefined;
  error: Error | undefined;
  /** Whether there are more than `items`: the sidebar's "View all". */
  hasMore: boolean;
  reload(): void;
  /** Moves at each conversation renamed, archived, restored or deleted here: a list of its own reads again. */
  changed: number;
  /** Its title: the API's, else the first message at hand, its party's name, the id in its key, or `NEW_CHAT`. */
  titleOf(conversation: ApiConversation): string;
  /** A tab's title: its conversation's, as it is now. */
  tabTitle(tab: Tab): string;
  /** The first message written in conversation `id`, as this page knows it: the title until the API has one. */
  setFirstMessage(id: string, text: string): void;
  /** The notes the commands run in conversation `id` answered, oldest first. */
  notesOf(id: string): CommandNote[];
  /** A command's answer in conversation `id`. */
  addNote(id: string, command: string, text: string): void;
  tabs: Tab[];
  /** Opens (or refreshes) the tab of `conversation`. */
  openTab(conversation: ApiConversation): void;
  /** Closes a tab; answers the tab to show instead when it was `active`. */
  closeTab(id: string): Tab | undefined;
  /** The conversation `from` was reset into `to`: its tab follows (to the new one's title). */
  replaced(from: string, to: string): void;
  /** The archived ones, the most recently active first; undefined until `loadArchived` read them. */
  archived: ApiConversation[] | undefined;
  loadArchived(): void;
  /** Archives, restores (`unarchive`) or deletes a conversation: from the list only. Its tab closes when it leaves the list. */
  hide(id: string, action: "archive" | "unarchive" | "delete"): Promise<void>;
  /** Titles a conversation with the operator's `title` (the API cleans it, as `/name` does); the lists are read again. */
  rename(id: string, title: string): Promise<void>;
}

const ChatsContext = createContext<Chats | undefined>(undefined);

export function useChats(): Chats {
  const chats = useContext(ChatsContext);
  if (chats === undefined) throw new Error("useChats: outside ChatsProvider");
  return chats;
}

export function ChatsProvider({ children }: { children: ReactNode }) {
  /** The first page, and when it was asked for (epoch ms): a slower answer to an older request never replaces it. */
  const [read, setRead] = useState<{ page: ApiPage<ApiConversation>; at: number }>();
  const first = read?.page;
  const [changed, setChanged] = useState(0);
  const [error, setError] = useState<Error>();
  const [firsts, setFirsts] = useState<Record<string, string>>({});
  const [notes, setNotes] = useState<Record<string, CommandNote[]>>({});
  const [tabs, setTabs] = useState<Tab[]>(() => load<Tab[]>(TABS, []).filter((tab) => typeof tab?.id === "string"));
  const [archived, setArchived] = useState<ApiConversation[]>();
  /** Put away by this page, with their activity then: left out of the pages read until newer activity lists one again. */
  const [gone, setGone] = useState<ReadonlyMap<string, number>>(new Map());

  const reload = useCallback(() => {
    const at = Date.now();
    api<ApiPage<ApiConversation>>(`/conversations?limit=${PAGE}`)
      .then((page) => (setRead((current) => (current !== undefined && current.at > at ? current : { page, at })), setError(undefined)))
      .catch((thrown: unknown) => setError(thrown instanceof Error ? thrown : new Error(String(thrown))));
  }, []);
  useEffect(reload, [reload]);
  usePolling(reload, every(10_000));

  useEffect(() => save(TABS, tabs.slice(-KEPT_TABS)), [tabs]);

  // The API's titles, by conversation.
  const titled = useMemo(() => {
    const byId = new Map<string, string>();
    for (const each of first?.items ?? []) if (each.title !== undefined) byId.set(each.conversationId, each.title);
    return byId;
  }, [first]);

  const titleOf = useCallback(
    (conversation: ApiConversation): string => {
      const known = conversation.title ?? titled.get(conversation.conversationId) ?? firsts[conversation.conversationId];
      if (known !== undefined) return known;
      const key = conversation.key;
      if (key === undefined || isDashboardKey(key)) return NEW_CHAT;
      const name = (conversation as ApiConversation & { party?: { name?: string } }).party?.name;
      if (name !== undefined && name.trim() !== "") return name;
      return key.slice(key.indexOf(":") + 1) || key;
    },
    [titled, firsts],
  );
  const tabTitle = useCallback((tab: Tab): string => titled.get(tab.id) ?? firsts[tab.id] ?? tab.title, [titled, firsts]);

  const setFirstMessage = useCallback((id: string, text: string) => {
    const title = cleanTitle(text);
    if (title === undefined) return;
    setFirsts((all) => (all[id] !== undefined ? all : { ...all, [id]: title }));
  }, []);

  const sent = useSentMessages();
  const { lastSentAt } = sent;

  const notesOf = useCallback((id: string): CommandNote[] => notes[id] ?? [], [notes]);
  const addNote = useCallback((id: string, command: string, text: string) => {
    setNotes((all) => ({ ...all, [id]: [...(all[id] ?? []), { id: nextNote++, command, text, at: Date.now() }] }));
  }, []);

  const openTab = useCallback(
    (conversation: ApiConversation) => {
      const tab: Tab = { id: conversation.conversationId, title: titleOf(conversation) };
      setTabs((all) => {
        const at = all.findIndex((each) => each.id === tab.id);
        if (at === -1) return [...all, tab].slice(-KEPT_TABS);
        const known = all[at];
        return known?.title === tab.title ? all : all.map((each, i) => (i === at ? tab : each));
      });
    },
    [titleOf],
  );

  const closeTab = useCallback(
    (id: string) => {
      const at = tabs.findIndex((tab) => tab.id === id);
      setTabs((all) => all.filter((tab) => tab.id !== id));
      return at === -1 ? undefined : (tabs[at + 1] ?? tabs[at - 1]);
    },
    [tabs],
  );

  const replaced = useCallback((from: string, to: string) => {
    setTabs((all) => all.map((tab) => (tab.id === from ? { ...tab, id: to } : tab)));
  }, []);

  // One with no key has nothing to show or do: left out; so is one this page just put away. One written to since goes first.
  const items = useMemo(() => {
    if (read === undefined) return undefined;
    const listed = read.page.items.filter((each) => each.key !== undefined && !gone.has(each.conversationId));
    return writtenFirst(listed, read.at, (each) => lastSentAt(each.conversationId));
  }, [read, gone, lastSentAt]);

  const loadArchived = useCallback(() => {
    api<ApiPage<ApiConversation>>(`/conversations?archived=1&limit=${ARCHIVED_PAGE}`)
      .then((page) => setArchived(page.items.filter((each) => each.key !== undefined)))
      .catch((thrown: unknown) => setError(thrown instanceof Error ? thrown : new Error(String(thrown))));
  }, []);

  const hide = useCallback(
    async (id: string, action: "archive" | "unarchive" | "delete") => {
      await post(`/conversations/${encodeURIComponent(id)}/${action}`);
      if (action === "unarchive") setGone((all) => new Map([...all].filter(([each]) => each !== id)));
      else {
        const at = first?.items.find((each) => each.conversationId === id)?.lastActivity ?? 0;
        setGone((all) => new Map([...all, [id, at]]));
        setTabs((all) => all.filter((tab) => tab.id !== id));
      }
      if (archived !== undefined) loadArchived();
      setChanged((n) => n + 1);
      reload();
    },
    [archived, first, loadArchived, reload],
  );

  const rename = useCallback(
    async (id: string, title: string) => {
      await post<ApiConversation>(`/conversations/${encodeURIComponent(id)}/rename`, { title } satisfies ApiRenameRequest);
      if (archived !== undefined) loadArchived();
      setChanged((n) => n + 1);
      reload();
    },
    [archived, loadArchived, reload],
  );

  // Active again since it was put away (a person wrote): the API lists it again, and so does this page.
  useEffect(() => {
    if (first === undefined || gone.size === 0) return;
    const back = first.items.filter((each) => (gone.get(each.conversationId) ?? Infinity) < (each.lastActivity ?? 0)).map((each) => each.conversationId);
    if (back.length > 0) setGone((all) => new Map([...all].filter(([id]) => !back.includes(id))));
  }, [first, gone]);

  const value: Chats = { items, error, hasMore: first?.next !== undefined, reload, changed, titleOf, tabTitle, setFirstMessage, notesOf, addNote, ...sent, tabs, openTab, closeTab, replaced, archived, loadArchived, hide, rename };
  return <ChatsContext.Provider value={value}>{children}</ChatsContext.Provider>;
}

/**
 * What the Settings dialog's App section (`components/pikit/app-settings.tsx`) says of the App's
 * composition (`ApiApp`), worked out here with no imports but types, so the kit's tests read it as it
 * is: where it runs, its components by what they are for, the line that sums it up, and the wiring
 * worth a look (a capability with a choice of providers, a keyed one, one nobody provides, the
 * pipelines' stages).
 */

import type { ApiApp } from "./admin-api.ts";

export type Component = ApiApp["components"][number];

export interface Group {
  title: string;
  components: Component[];
}

/**
 * What a component is for: the first kind whose capabilities it provides (`storage.` is a family), else
 * whose prefix its name has. A channel provides only routes, so it is known by its name.
 */
const KINDS: { title: string; capabilities: string[]; prefixes: string[] }[] = [
  { title: "Channels", capabilities: [], prefixes: ["channel-"] },
  { title: "Agents and models", capabilities: ["agent.runtime", "model.provider", "agent.extension"], prefixes: ["runtime-", "provider-", "router-", "extension-", "agents-"] },
  { title: "Tools", capabilities: ["agent.tool"], prefixes: ["tool-"] },
  { title: "Data", capabilities: ["storage.", "conversations.registry", "settings", "outbound.queue"], prefixes: ["storage-", "conversations-"] },
  { title: "Integrations", capabilities: ["repo.github", "proposals"], prefixes: [] },
  { title: "Dashboard and admin", capabilities: ["admin.auth"], prefixes: ["admin-"] },
  { title: "Platform", capabilities: ["secrets", "wakeups", "execution"], prefixes: ["actors-", "deployment-", "secrets-", "execution-"] },
];
export const OTHER = "Other";

const provides = (component: Component, capabilities: string[]) =>
  component.provides.some((name) => capabilities.some((each) => (each.endsWith(".") ? name.startsWith(each) : name === each)));

export function kindOf(component: Component): string {
  const kind = KINDS.find((each) => provides(component, each.capabilities) || each.prefixes.some((prefix) => component.name.startsWith(prefix)));
  return kind?.title ?? OTHER;
}

/** The components by kind, in the kinds' order (Other last), each kind's by name; no empty kind. */
export function groupsOf(components: Component[]): Group[] {
  const titles = [...KINDS.map((kind) => kind.title), OTHER];
  return titles
    .map((title) => ({ title, components: components.filter((component) => kindOf(component) === title).sort((a, b) => a.name.localeCompare(b.name)) }))
    .filter((group) => group.components.length > 0);
}

/** Where the App runs, in words. */
export function placeOf(target: string): string {
  return target === "durable" ? "Cloudflare" : target === "server" ? "a server" : target;
}

/** The platforms its channels talk on, by the first word after `channel-` (`channel-telegram-webhook` is Telegram). */
export function channelsOf(components: Component[]): string[] {
  const names = components
    .filter((component) => component.name.startsWith("channel-"))
    .map((component) => component.name.slice("channel-".length).split("-")[0] ?? "")
    .filter((word) => word !== "")
    .map((word) => word.charAt(0).toLocaleUpperCase() + word.slice(1));
  return [...new Set(names)];
}

const plural = (count: number, one: string) => `${count} ${one}${count === 1 ? "" : "s"}`;
const list = (words: string[]) => (words.length <= 1 ? (words[0] ?? "") : `${words.slice(0, -1).join(", ")} and ${words.at(-1)}`);

/**
 * The App in one line: where it talks (its channels, and this dashboard), with how many agents (when
 * read) and tools, out of how many components.
 */
export function summaryOf(app: ApiApp, agents: number | undefined): string {
  const where = [...channelsOf(app.components), "this dashboard"];
  const tools = app.components.filter((component) => kindOf(component) === "Tools").length;
  const with_ = [...(agents === undefined ? [] : [plural(agents, "agent")]), plural(tools, "tool")];
  return `Talks on ${list(where)}, with ${list(with_)}: ${plural(app.components.length, "component")} in all.`;
}

/** Who provides `capability` for the App: its keys' providers, the one selected, or every provider. */
export function providersOf(app: ApiApp, capability: string): string[] {
  const found = app.capabilities[capability];
  if (found === undefined) return [];
  if (found.keys !== undefined && Object.keys(found.keys).length > 0) return [...new Set(Object.values(found.keys))];
  return found.selected !== undefined ? [found.selected] : found.providers;
}

/** The other components that use what `component` provides (requiring it, or using it when installed). */
export function usersOf(app: ApiApp, component: Component): string[] {
  return app.components
    .filter((other) => other.name !== component.name && [...other.requires, ...other.optional].some((capability) => component.provides.includes(capability)))
    .map((other) => other.name);
}

/**
 * A single capability more than one component provides, with the one the App uses. One every provider
 * of is used (`agent.tool`, a keyed one) is no choice.
 */
export interface Choice {
  capability: string;
  providers: string[];
  selected: string;
}

/** One key of a keyed capability (an `http.route`'s path) and who provides it. */
export interface Keyed {
  capability: string;
  key: string;
  provider: string;
}

/** A capability some components would use, which nothing provides. */
export interface Missing {
  capability: string;
  wantedBy: string[];
}

export interface Stage {
  id: string;
  priority?: number;
}

export interface Wiring {
  choices: Choice[];
  keyed: Keyed[];
  missing: Missing[];
  pipelines: { name: string; stages: Stage[] }[];
}

/** A pipeline's stage as the API gives it (`{ id, priority }`); anything else by its JSON. */
function stageOf(value: unknown): Stage {
  if (typeof value === "object" && value !== null && typeof (value as { id?: unknown }).id === "string") {
    const { id, priority } = value as { id: string; priority?: unknown };
    return typeof priority === "number" ? { id, priority } : { id };
  }
  return { id: JSON.stringify(value) };
}

export function wiringOf(app: ApiApp): Wiring {
  const capabilities = Object.entries(app.capabilities).sort(([a], [b]) => a.localeCompare(b));
  const choices = capabilities
    .flatMap(([name, capability]) => (capability.providers.length > 1 && capability.selected !== undefined ? [{ capability: name, providers: capability.providers, selected: capability.selected }] : []));
  const keyed = capabilities.flatMap(([name, capability]) =>
    Object.entries(capability.keys ?? {})
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([key, provider]) => ({ capability: name, key, provider })),
  );
  const wanted = new Map<string, string[]>();
  for (const component of app.components) {
    for (const capability of component.optional) {
      if ((app.capabilities[capability]?.providers.length ?? 0) > 0) continue;
      wanted.set(capability, [...(wanted.get(capability) ?? []), component.name]);
    }
  }
  const missing = [...wanted].sort(([a], [b]) => a.localeCompare(b)).map(([capability, wantedBy]) => ({ capability, wantedBy }));
  const pipelines = Object.entries(app.pipelines)
    .filter(([, stages]) => stages.length > 0)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, stages]) => ({ name, stages: stages.map(stageOf) }));
  return { choices, keyed, missing, pipelines };
}

/**
 * The outbound queue as the dashboard follows it, read once for every page that asks (the sidebar's
 * dot on Delivery, the Delivery view, a conversation's note): the pieces it holds now (`GET
 * /admin/api/delivery/pending`, every page) and its receipts (`GET /admin/api/delivery/receipts`: a
 * feed, read from the oldest the queue keeps, then on from its cursor), folded per answer
 * (`delivery.ts`: what is stuck, not delivered, possibly twice). It reads while a page uses it and the
 * operator is there (`usePolling`), at most once every `MIN_GAP_MS` however many pages ask.
 *
 * Without a queue to read here (`404 not_installed`: none is installed, or on Cloudflare, where each
 * conversation's queue is in its own Durable Object) it stops asking, and says why (`unavailable`).
 */

import { useEffect, useMemo, useSyncExternalStore } from "react";
import { every, usePolling } from "./activity.ts";
import { api, type ApiPage, type ApiPendingPiece, type ApiReceiptsPage, ApiFailure } from "./api.ts";
import { type DeliveryProblems, EMPTY_TALLY, problemsOf, type ReceiptsTally, tallyReceipts } from "./delivery.ts";

/** However many pages ask, the queue is read at most this often (ms). */
const MIN_GAP_MS = 3_000;
const PAGE = 500;
/** Pages of receipts read in one go: the rest at the next read. */
const RECEIPT_PAGES = 20;
/** Pages of pending pieces read: past them, `pendingMore`. */
const PENDING_PAGES = 10;

export interface DeliveryFeed {
  /** The pieces held now; `undefined` until read. */
  pending?: ApiPendingPiece[];
  /** More pieces are held than were read. */
  pendingMore: boolean;
  tally: ReceiptsTally;
  /** Every receipt the queue keeps was read once. */
  caughtUp: boolean;
  /** Some receipts were pruned before they were read: the count misses them. */
  gap: boolean;
  /** When it was last read, on this browser's clock. */
  readAt?: number;
  error?: Error;
  /** Why there is nothing to read here (the API's words), once it said so. */
  unavailable?: string;
}

let state: DeliveryFeed = { pendingMore: false, tally: EMPTY_TALLY, caughtUp: false, gap: false };
const listeners = new Set<() => void>();
let after: string | undefined;
let reading = false;
let started = 0;

const set = (change: Partial<DeliveryFeed>): void => {
  state = { ...state, ...change };
  for (const listener of listeners) listener();
};

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

async function readPending(): Promise<{ items: ApiPendingPiece[]; more: boolean }> {
  const items: ApiPendingPiece[] = [];
  let cursor: string | undefined;
  for (let pages = 0; pages < PENDING_PAGES; pages++) {
    const page = await api<ApiPage<ApiPendingPiece>>(`/delivery/pending?limit=${PAGE}${cursor === undefined ? "" : `&cursor=${encodeURIComponent(cursor)}`}`);
    items.push(...page.items);
    cursor = page.next;
    if (cursor === undefined) return { items, more: false };
  }
  return { items, more: true };
}

/** Reads the queue now, unless it was read within `MIN_GAP_MS`, is being read, or cannot be. */
export function refreshDelivery(): void {
  if (reading || state.unavailable !== undefined || Date.now() - started < MIN_GAP_MS) return;
  reading = true;
  started = Date.now();
  const read = async () => {
    const pending = await readPending();
    let tally = state.tally;
    let gap = state.gap;
    let caughtUp = false;
    for (let pages = 0; pages < RECEIPT_PAGES; pages++) {
      const page = await api<ApiReceiptsPage>(`/delivery/receipts?limit=${PAGE}${after === undefined ? "" : `&after=${encodeURIComponent(after)}`}`);
      tally = tallyReceipts(tally, page.items);
      gap ||= page.gap;
      after = page.next ?? after;
      if (page.items.length < PAGE) {
        caughtUp = true;
        break;
      }
    }
    set({ pending: pending.items, pendingMore: pending.more, tally, gap, caughtUp: state.caughtUp || caughtUp, readAt: Date.now(), error: undefined });
  };
  read()
    .catch((thrown: unknown) => {
      if (thrown instanceof ApiFailure && thrown.status === 404 && thrown.body.error === "not_installed") set({ unavailable: thrown.message, error: undefined });
      else set({ error: thrown instanceof Error ? thrown : new Error(String(thrown)) });
    })
    .finally(() => (reading = false));
}

/**
 * The queue, followed while `enabled` (the App has an `outbound.queue`), read again every `everyMs`
 * (slower on Cloudflare) while the operator is here; with its problems, per answer.
 */
export function useDelivery(enabled: boolean, everyMs = 30_000): { feed: DeliveryFeed; problems: DeliveryProblems | undefined } {
  const feed = useSyncExternalStore(subscribe, () => state);
  useEffect(() => {
    if (enabled) refreshDelivery();
  }, [enabled]);
  usePolling(refreshDelivery, enabled ? every(everyMs) : undefined);
  const problems = useMemo(
    () => (feed.pending === undefined || feed.readAt === undefined ? undefined : problemsOf(feed.pending, feed.tally, feed.readAt)),
    [feed.pending, feed.tally, feed.readAt],
  );
  return { feed, problems };
}

/**
 * Delivery's problems (SPEC §5), worked out from what the outbound queue says (`ApiPendingPiece`,
 * `ApiReceipt`) with no imports but types, so the kit's tests read it as it is. Per answer, never per
 * piece: an answer's pieces share its `idempotencyKey` (`answerKey`: `${conversationId}:${requestId}`).
 *
 * - **Stuck**: an answer with a piece the queue still holds that was tried and waits to go again
 *   (`retrying`: it failed, the platform asked to wait, or a stop cut it), or that has waited longer
 *   than `STUCK_AFTER_MS` (the queue sends one in seconds: its channel has no transport attached, or it
 *   waits behind a stuck one of its conversation).
 * - **Not delivered**: an answer with a piece the queue gave up (`abandoned`: a permanent refusal, or
 *   24 hours), with why and when.
 * - **Possibly twice**: an answer delivered with a piece the platform may have received twice
 *   (`possibleDuplicate`): nothing to do, said for what a person may have seen.
 * - Every other answer the receipts name was **delivered**: counted, never listed. The receipts are
 *   pruned (outbound-durable keeps 7 days of deliveries, 30 of abandoned pieces), so the count holds
 *   since the oldest delivered receipt read (`since`), and less when some were pruned before they were
 *   read (`gap`).
 */

import type { ApiPendingPiece, ApiReceipt } from "./admin-api.ts";

/** An answer whose pieces have waited this long (ms) without being delivered is stuck. */
export const STUCK_AFTER_MS = 60_000;
/** An answer given up within this long (ms) still asks for a look (the sidebar's dot). */
export const RECENT_MS = 24 * 60 * 60_000;

/** One answer: its key, its conversation (the API's id, when the key is a run's answer), its channel. */
export interface AnswerRef {
  key: string;
  conversationId?: string;
  conversationKey: string;
  channel: string;
}

export interface StuckAnswer extends AnswerRef {
  /** Its pieces still held. */
  pieces: number;
  /** One was tried and waits to go again; otherwise none was tried yet. */
  retrying: boolean;
  /** The most sends one of its pieces had. */
  attempts: number;
  /** Why its last try did not deliver it, short. */
  lastError?: string;
  /** When the queue tries again (its soonest piece), on the App's clock; absent while sending. */
  nextAttemptAt?: number;
  /** When its oldest held piece was stored. */
  since: number;
  /** Its next send may repeat one that reached the platform. */
  possibleDuplicate: boolean;
}

export interface UndeliveredAnswer extends AnswerRef {
  /** Why its first abandoned piece was given up. */
  reason: string;
  /** When the queue gave its first piece up. */
  at: number;
  /** The most sends one of its abandoned pieces had. */
  attempts: number;
  /** Its pieces given up, and those delivered (a person got part of it). */
  abandoned: number;
  delivered: number;
}

export interface DuplicateAnswer extends AnswerRef {
  /** Its pieces that may have been received twice. */
  pieces: number;
  /** When the last of them was delivered. */
  at: number;
}

/** What the receipts read so far say, folded per answer as the feed is read on (`tallyReceipts`). */
export interface ReceiptsTally {
  /** Pieces delivered, per answer with any. */
  delivered: ReadonlyMap<string, number>;
  abandoned: ReadonlyMap<string, UndeliveredAnswer>;
  duplicates: ReadonlyMap<string, DuplicateAnswer>;
  /** When the oldest delivered receipt read settled: since when the count holds. */
  since?: number;
}

export const EMPTY_TALLY: ReceiptsTally = { delivered: new Map(), abandoned: new Map(), duplicates: new Map() };

const refOf = (piece: { idempotencyKey: string; conversationId?: string; conversationKey: string; channel: string }): AnswerRef => ({
  key: piece.idempotencyKey,
  ...(piece.conversationId !== undefined && { conversationId: piece.conversationId }),
  conversationKey: piece.conversationKey,
  channel: piece.channel,
});

/** `tally` with `receipts` (in the order they settled) folded in; `tally` itself is left as it was. */
export function tallyReceipts(tally: ReceiptsTally, receipts: readonly ApiReceipt[]): ReceiptsTally {
  if (receipts.length === 0) return tally;
  const delivered = new Map(tally.delivered);
  const abandoned = new Map(tally.abandoned);
  const duplicates = new Map(tally.duplicates);
  let since = tally.since;
  for (const receipt of receipts) {
    const key = receipt.idempotencyKey;
    if (receipt.outcome.kind === "abandoned") {
      const before = abandoned.get(key);
      abandoned.set(
        key,
        before === undefined
          ? { ...refOf(receipt), reason: receipt.outcome.reason, at: receipt.at, attempts: receipt.attempts, abandoned: 1, delivered: delivered.get(key) ?? 0 }
          : { ...before, attempts: Math.max(before.attempts, receipt.attempts), abandoned: before.abandoned + 1 },
      );
      continue;
    }
    delivered.set(key, (delivered.get(key) ?? 0) + 1);
    const given = abandoned.get(key);
    if (given !== undefined) abandoned.set(key, { ...given, delivered: given.delivered + 1 });
    since = since === undefined ? receipt.at : Math.min(since, receipt.at);
    if (receipt.outcome.possibleDuplicate) {
      const before = duplicates.get(key);
      duplicates.set(key, { ...refOf(receipt), pieces: (before?.pieces ?? 0) + 1, at: Math.max(before?.at ?? 0, receipt.at) });
    }
  }
  return { delivered, abandoned, duplicates, ...(since !== undefined && { since }) };
}

export interface DeliveryProblems {
  /** The oldest first. */
  stuck: StuckAnswer[];
  /** The latest given up first. */
  undelivered: UndeliveredAnswer[];
  /** The latest first; none given up. */
  duplicates: DuplicateAnswer[];
  /** Answers on their way: held for less than `STUCK_AFTER_MS`, never tried yet. */
  onTheirWay: number;
  /** Answers the receipts say were delivered whole: none held, none given up. */
  delivered: number;
  /** When the oldest delivered receipt read settled. */
  since?: number;
}

/** The answers that need a look, from the pieces held now (`pending`) and the receipts read, at `now`. */
export function problemsOf(pending: readonly ApiPendingPiece[], tally: ReceiptsTally, now: number): DeliveryProblems {
  const held = new Map<string, ApiPendingPiece[]>();
  for (const piece of pending) held.set(piece.idempotencyKey, [...(held.get(piece.idempotencyKey) ?? []), piece]);

  const stuck: StuckAnswer[] = [];
  let onTheirWay = 0;
  for (const [, pieces] of held) {
    const first = pieces[0] as ApiPendingPiece;
    const since = Math.min(...pieces.map((piece) => piece.storedAt));
    const retrying = pieces.some((piece) => piece.state === "retrying");
    if (!retrying && now - since <= STUCK_AFTER_MS) {
      onTheirWay += 1;
      continue;
    }
    const failed = [...pieces].sort((a, b) => a.index - b.index).find((piece) => piece.lastError !== undefined);
    const next = pieces.flatMap((piece) => (piece.nextAttemptAt === undefined ? [] : [piece.nextAttemptAt]));
    stuck.push({
      ...refOf(first),
      pieces: pieces.length,
      retrying,
      attempts: Math.max(...pieces.map((piece) => piece.attempts)),
      ...(failed?.lastError !== undefined && { lastError: failed.lastError }),
      ...(next.length > 0 && { nextAttemptAt: Math.min(...next) }),
      since,
      possibleDuplicate: pieces.some((piece) => piece.possibleDuplicate),
    });
  }
  stuck.sort((a, b) => a.since - b.since);

  const undelivered = [...tally.abandoned.values()].sort((a, b) => b.at - a.at);
  const duplicates = [...tally.duplicates.values()].filter((answer) => !tally.abandoned.has(answer.key)).sort((a, b) => b.at - a.at);
  let delivered = 0;
  for (const key of tally.delivered.keys()) if (!tally.abandoned.has(key) && !held.has(key)) delivered += 1;
  return { stuck, undelivered, duplicates, onTheirWay, delivered, ...(tally.since !== undefined && { since: tally.since }) };
}

/** Whether an operator should look now: an answer stuck, or one given up within `RECENT_MS`. */
export function needsAttention(problems: DeliveryProblems, now: number): boolean {
  return problems.stuck.length > 0 || problems.undelivered.some((answer) => now - answer.at <= RECENT_MS);
}

/**
 * A small router over the History API, under /admin (admin-api answers every path but `/admin/assets/`
 * and its files with index.html, so a reload of any page works). Paths here are relative to /admin:
 * `/conversations/abc` is `/admin/conversations/abc`.
 *
 * A parameter is one path segment, encoded in a link (`encodeURIComponent`: an id such as
 * `email:ana@empresa.com~1` or one with `/`) and decoded by `match`.
 */

import { type AnchorHTMLAttributes, useSyncExternalStore } from "react";

export const BASE = "/admin";

function subscribe(onChange: () => void): () => void {
  window.addEventListener("popstate", onChange);
  return () => window.removeEventListener("popstate", onChange);
}

const path = (): string => {
  const { pathname } = window.location;
  const relative = pathname.startsWith(BASE) ? pathname.slice(BASE.length) : pathname;
  return relative === "" ? "/" : relative;
};

/** The current path, relative to /admin. */
export function usePath(): string {
  return useSyncExternalStore(subscribe, path);
}

export function navigate(to: string, options: { replace?: boolean } = {}): void {
  const url = `${BASE}${to}`;
  if (options.replace === true) window.history.replaceState(null, "", url);
  else window.history.pushState(null, "", url);
  window.dispatchEvent(new PopStateEvent("popstate"));
}

/**
 * The parameters of `pattern` (`/conversations/:id`) in `pathname`, or `undefined` when it does not
 * match.
 */
export function match(pattern: string, pathname: string): Record<string, string> | undefined {
  const want = pattern.split("/").filter(Boolean);
  const have = pathname.split("/").filter(Boolean);
  if (want.length !== have.length) return undefined;
  const params: Record<string, string> = {};
  for (const [i, segment] of want.entries()) {
    const value = have[i] ?? "";
    if (segment.startsWith(":")) {
      try {
        params[segment.slice(1)] = decodeURIComponent(value);
      } catch {
        return undefined;
      }
    } else if (segment !== value) return undefined;
  }
  return params;
}

/** The path of a page with `id` as one segment: `pagePath("/conversations", id)`. */
export function pagePath(base: string, id: string): string {
  return `${base}/${encodeURIComponent(id)}`;
}

/** A link inside the dashboard: `to` is relative to /admin. */
export function Link({ to, onClick, ...rest }: AnchorHTMLAttributes<HTMLAnchorElement> & { to: string }) {
  return (
    <a
      {...rest}
      href={`${BASE}${to}`}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey) return;
        event.preventDefault();
        navigate(to);
      }}
    />
  );
}

/**
 * The Settings dialog's sections: the dashboard's own (`General`, kept in this browser) and one per
 * installed component that brings one. Each folder of `src/settings/` is one, found when the dashboard
 * is built (nothing is loaded at run time), as views are (`views.ts`). Its `index.tsx` default-exports
 * `defineSettings({ … })`:
 *
 *   export default defineSettings({
 *     id: "router-basic",                 // the folder's name: the component's
 *     title: "Agent",
 *     icon: User,
 *     group: "Agents",                    // the left column's heading (default "Components")
 *     requires: ["settings"],             // shown only when these capabilities are installed
 *     keywords: ["prompt", "model"],      // what the search box finds it by, besides its title
 *     component: AgentSettings,
 *   });
 *
 * A component installs its folder here (`pikit add`, component.json's `settings`). Its values are the
 * component's settings (settings-store's routes, `/admin/api/settings/:component`): `useSettings`
 * reads one component's, with its schema, and saves it whole. A simple section renders from the schema
 * alone (`SchemaSettings`, `components/pikit/settings.tsx`); a custom one places its own controls.
 */

import { type ComponentType, createContext, useCallback, useContext, useEffect, useState } from "react";
import { type ApiApp, api } from "./api.ts";

export interface SettingsSectionDefinition {
  /** The folder's name: the component's. */
  id: string;
  title: string;
  icon?: ComponentType<{ className?: string; width?: number; height?: number; strokeWidth?: number }>;
  /** The heading it is listed under (default `Components`); the dashboard's own come first. */
  group?: string;
  /** Its place in its group, lowest first (default 100). */
  order?: number;
  /** Capabilities that must be provided in the App for it to show. */
  requires?: string[];
  /** Words the search box finds it by, besides its title. */
  keywords?: string[];
  component: ComponentType;
}

export function defineSettings(section: SettingsSectionDefinition): SettingsSectionDefinition {
  return section;
}

/** Opens a section of the dialog by its id: a section linking to another's (the dialog provides it). */
export const SettingsNavigation = createContext<(id: string) => void>(() => {});

/** The dialog's way to open another section, by its id (`"router-basic"`). */
export function useOpenSettingsSection(): (id: string) => void {
  return useContext(SettingsNavigation);
}

/** The groups listed first, in this order; any other after them, by name. */
const GROUPS = ["Dashboard", "Agents", "Components"];

const found = import.meta.glob<{ default: SettingsSectionDefinition }>("../settings/*/index.tsx", { eager: true });

/** Every section of `src/settings/`, by group, then order, then title. */
export const settingsSections: SettingsSectionDefinition[] = Object.entries(found)
  .map(([file, module]) => {
    const section = module.default;
    const folder = file.split("/").at(-2);
    if (section?.id !== folder) throw new Error(`src/settings/${folder}/index.tsx must default-export defineSettings({ id: "${folder}", … })`);
    return section;
  })
  .sort(bySectionOrder);

export function groupOf(section: SettingsSectionDefinition): string {
  return section.group ?? "Components";
}

export function bySectionOrder(a: SettingsSectionDefinition, b: SettingsSectionDefinition): number {
  const rank = (group: string) => (GROUPS.includes(group) ? GROUPS.indexOf(group) : GROUPS.length);
  return (
    rank(groupOf(a)) - rank(groupOf(b)) ||
    groupOf(a).localeCompare(groupOf(b)) ||
    (a.order ?? 100) - (b.order ?? 100) ||
    a.title.localeCompare(b.title)
  );
}

/** The sections whose capabilities `app` provides. */
export function visibleSettings(app: ApiApp): SettingsSectionDefinition[] {
  const provided = (name: string) => (app.capabilities[name]?.providers.length ?? 0) > 0;
  return settingsSections.filter((section) => (section.requires ?? []).every(provided));
}

/** A JSON Schema, as the routes answer it (TypeBox's). */
export type JsonSchema = {
  type?: string;
  title?: string;
  description?: string;
  default?: unknown;
  enum?: unknown[];
  const?: unknown;
  anyOf?: JsonSchema[];
  properties?: Record<string, JsonSchema>;
  required?: string[];
  items?: JsonSchema;
  format?: string;
  minimum?: number;
  maximum?: number;
  maxLength?: number;
  /** values that fit: the first is a text field's placeholder */
  examples?: unknown[];
  [keyword: string]: unknown;
};

export type SettingsValue = Record<string, unknown>;

/** One component's settings, as settings-store's routes answer them. */
export interface ApiSettingsSection {
  component: string;
  schema: JsonSchema;
  defaults: SettingsValue;
  value: SettingsValue;
}

/** One component's settings, and saving them whole (`PUT`): the answer replaces what is shown. */
export interface ComponentSettings {
  section: ApiSettingsSection | undefined;
  error: Error | undefined;
  /** Saves `value` as the component's whole value; rejects with the API's refusal. */
  save(value: SettingsValue): Promise<void>;
  saving: boolean;
}

/** `component`'s settings (`GET /admin/api/settings/:component`). */
export function useSettings(component: string): ComponentSettings {
  const [section, setSection] = useState<ApiSettingsSection>();
  const [error, setError] = useState<Error>();
  const [saving, setSaving] = useState(false);
  const path = `/settings/${encodeURIComponent(component)}`;

  useEffect(() => {
    let live = true;
    api<ApiSettingsSection>(path).then(
      (read) => live && (setSection(read), setError(undefined)),
      (thrown: unknown) => live && setError(thrown instanceof Error ? thrown : new Error(String(thrown))),
    );
    return () => {
      live = false;
    };
  }, [path]);

  const save = useCallback(
    async (value: SettingsValue) => {
      setSaving(true);
      try {
        const saved = await api<ApiSettingsSection>(path, { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify(value) });
        setSection(saved);
        setError(undefined);
      } finally {
        setSaving(false);
      }
    },
    [path],
  );

  return { section, error, save, saving };
}

/** The choices a schema offers: an `enum`, or an `anyOf` of `const`s (TypeBox's `Union` of `Literal`s); `undefined` when it offers none. */
export function choicesOf(schema: JsonSchema | undefined): string[] | undefined {
  if (schema === undefined) return undefined;
  if (Array.isArray(schema.enum)) return schema.enum.filter((each): each is string => typeof each === "string");
  if (Array.isArray(schema.anyOf) && schema.anyOf.every((each) => typeof each.const === "string")) return schema.anyOf.map((each) => each.const as string);
  return undefined;
}

/**
 * What the shell (`app.tsx`) gives the pages: the App's composition, its agents, its slash commands, the views it shows,
 * the operator, a new chat (`newChat`), a conversation's menu (`conversationActions`: the sidebar's rows'
 * and the conversation's header's), and two places a page can fill: the tab bar's right end
 * (`TabActions`: a conversation's Context button and its menu) and the side panel next to the main pane
 * (`SidePanel`: a conversation's Context).
 */

import { createContext, type ReactNode, useContext, useEffect } from "react";
import { createPortal } from "react-dom";
import type { ActionsMenuItem } from "@/components/bui/ActionsMenu";
import type { ApiAgent, ApiApp, ApiCommand, ApiConversation } from "./api.ts";
import type { View } from "./views.ts";

export interface ShellState {
  app: ApiApp;
  /** The App's agents (`GET /admin/api/agents`), by name; undefined until read. */
  agents?: ApiAgent[];
  /** Reads the agents again: after an operator made, changed or removed a live one. */
  reloadAgents(): void;
  /** The App's slash commands (`GET /admin/api/commands`), by name; undefined until read. */
  commands?: ApiCommand[];
  /** Opens a new chat (New chat, its draft empty), with `agent` chosen when given. */
  newChat(agent?: string): void;
  /** A conversation's menu (Rename, Archive or Restore when `archived`, Delete), as its sidebar row has it. */
  conversationActions(conversation: ApiConversation, archived: boolean): ActionsMenuItem[];
  /** The views the App's composition allows, in sidebar order. */
  views: View[];
  /** The signed-in operator's id, when this browser signed in (`ApiSession.operator`). */
  operator?: string;
  /** Where the tab bar's right end and the side panel are, once mounted. */
  slots: { actions: HTMLElement | null; side: HTMLElement | null };
}

export const ShellContext = createContext<ShellState | undefined>(undefined);

export function useShell(): ShellState {
  const shell = useContext(ShellContext);
  if (shell === undefined) throw new Error("useShell: outside the dashboard's shell");
  return shell;
}

/** Shown at the tab bar's right end while the page is. */
export function TabActions({ children }: { children: ReactNode }) {
  const target = useContext(ShellContext)?.slots.actions;
  return target === null || target === undefined ? null : createPortal(children, target);
}

/** A panel of its own next to the main pane (wide screens), while the page is. */
export function SidePanel({ children }: { children: ReactNode }) {
  const target = useContext(ShellContext)?.slots.side;
  return target === null || target === undefined ? null : createPortal(children, target);
}

/** The App's name: `ApiApp` has none yet, so "Pikit" unless one is there. */
export function appName(app: ApiApp): string {
  const name = (app as { name?: unknown }).name;
  return typeof name === "string" && name.trim() !== "" ? name : "Pikit";
}

/**
 * The browser tab's title while a page shows: `<what> · <App>`, or the App's name alone. Every page of
 * the shell sets it (the shell does, from the page it renders), so it never keeps a page's that left.
 */
export function usePageTitle(what: string | undefined, app = "Pikit"): void {
  useEffect(() => {
    document.title = what === undefined || what.trim() === "" ? app : `${what} · ${app}`;
  }, [what, app]);
}

/**
 * Views: each folder of `src/views/` is one, found when the dashboard is built (nothing is loaded
 * at run time). Its `index.tsx` default-exports `defineView({ … })`:
 *
 *   export default defineView({
 *     id: "memory",                       // the folder's name; its pages live under /memory
 *     title: "Memory",
 *     icon: Brain,
 *     requires: ["memory"],               // shown only when these capabilities are installed
 *     pages: [{ path: "/memory", component: MemoryPage }],
 *     badge: MemoryBadge,                 // optional: a dot on its sidebar item when it has something to show
 *   });
 *
 * A view whose `requires` are not all in the App's composition does not appear (SPEC §5). A component
 * that brings a view installs its folder here (`pikit add`, or `shadcn add @pikit/<view>`).
 */

import type { ComponentType } from "react";
import type { ApiApp } from "./api.ts";

export interface ViewPage {
  /** Relative to /admin, starting with the view's `/<id>`; `:name` is a parameter. */
  path: string;
  component: ComponentType<{ params: Record<string, string> }>;
  /** The page fills the main pane and scrolls itself (a chat); otherwise it is shown in a padded, scrolling column. */
  fill?: boolean;
}

export interface View {
  /** The folder's name. */
  id: string;
  title: string;
  icon?: ComponentType<{ className?: string }>;
  /** Capabilities that must be provided in the App for the view to show. */
  requires?: string[];
  /** Its place in the sidebar, lowest first (default 100). `conversations` is the chat, not a sidebar item. */
  order?: number;
  /** Its pages; the first one is the sidebar's link. */
  pages: ViewPage[];
  /**
   * Shown on its sidebar item's icon (collapsed too) while the view shows in the sidebar: a component
   * that reads what it needs (polled as a page polls: `useApi(path, every(ms))`) and renders
   * `SidebarDot` (`bui/SidebarNav`) when the view has something the operator should see, nothing
   * otherwise. Delivery's says an answer is stuck or was not delivered.
   */
  badge?: ComponentType;
}

export function defineView(view: View): View {
  for (const page of view.pages) {
    if (page.path !== `/${view.id}` && !page.path.startsWith(`/${view.id}/`)) {
      throw new Error(`view "${view.id}": page ${page.path} is not under /${view.id}`);
    }
  }
  return view;
}

const found = import.meta.glob<{ default: View }>("../views/*/index.tsx", { eager: true });

/** Every view of `src/views/`, in sidebar order. */
export const views: View[] = Object.entries(found)
  .map(([file, module]) => {
    const view = module.default;
    const folder = file.split("/").at(-2);
    if (view?.id !== folder) throw new Error(`src/views/${folder}/index.tsx must default-export defineView({ id: "${folder}", … })`);
    return view;
  })
  .sort((a, b) => (a.order ?? 100) - (b.order ?? 100) || a.title.localeCompare(b.title));

/** The views whose capabilities `app` provides. */
export function visibleViews(app: ApiApp): View[] {
  const provided = (name: string) => (app.capabilities[name]?.providers.length ?? 0) > 0;
  return views.filter((view) => (view.requires ?? []).every(provided));
}
